import React from "react";
import MainNav from "../../MainNav/MainNav";
import ArtistManagerNav from "../ArtistManagerNav/ArtistManagerNav";
import "./ArtistManagerDashboard.css";

function ArtistManagerDashboard() {
  return (
    <div className="dashboard-page">
      <MainNav />
      <ArtistManagerNav />
      <main className="dashboard-main">
        <div className="dashboard-container">
          <h1 className="dashboard-title">Artist Manager Dashboard</h1>
          <p className="dashboard-subtitle">Welcome to your artist management portal</p>
        </div>
      </main>
    </div>
  );
}

export default ArtistManagerDashboard;
